#include <string>
#include <vector>
#include <algorithm>

using namespace std;

class Solution {
    static constexpr int MOD = 1'000'000'007;

    vector<int> toBaseB(string s, int b) {
        long long n = stoll(s);
        if (n == 0) return {0};
        vector<int> digits;
        while (n > 0) {
            digits.push_back(n % b);
            n /= b;
        }
        reverse(digits.begin(), digits.end());
        return digits;
    }

    int countValid(const vector<int>& digits, int b) {
        int sz = digits.size();
        vector<vector<vector<vector<int>>>> memo(sz, vector<vector<vector<int>>>(b + 1, vector<vector<int>>(2, vector<int>(2, -1))));

        auto dfs = [&](auto& self, int pos, int last, bool isTight, bool isLeading) -> int {
            if (pos == sz) return 1;
            if (memo[pos][last][isTight][isLeading] != -1) return memo[pos][last][isTight][isLeading];
            int limit = isTight ? digits[pos] : b - 1;
            long long res = 0;
            for (int d = 0; d <= limit; ++d) {
                if (isLeading && d == 0) {
                    res = (res + self(self, pos + 1, 0, isTight && (d == limit), true)) % MOD;
                } else {
                    if (d >= last) {
                        res = (res + self(self, pos + 1, d, isTight && (d == limit), false)) % MOD;
                    }
                }
            }
            return memo[pos][last][isTight][isLeading] = res;
        };
        return dfs(dfs, 0, 0, true, true);
    }

    bool isValid(string s, int b) {
        auto digs = toBaseB(s, b);
        for (size_t i = 0; i + 1 < digs.size(); ++i) {
            if (digs[i] > digs[i + 1]) return false;
        }
        return true;
    }

public:
    int countNumbers(string l, string r, int b) {
        int cntR = countValid(toBaseB(r, b), b);
        int cntL = countValid(toBaseB(l, b), b);
        int ans = (cntR - cntL + (isValid(l, b) ? 1 : 0)) % MOD;
        return (ans + MOD) % MOD;
    }
};

import java.util.*;

class Solution {
    static final int MOD = 1_000_000_007;

    public int countNumbers(String l, String r, int b) {
        int cntR = countValid(toBaseB(r, b), b);
        int cntL = countValid(toBaseB(l, b), b);
        int ans = (cntR - cntL + (isValid(l, b) ? 1 : 0)) % MOD;
        return (ans + MOD) % MOD;
    }

    private List<Integer> toBaseB(String s, int b) {
        long n = Long.parseLong(s);
        if (n == 0) return Collections.singletonList(0);
        List<Integer> digits = new ArrayList<>();
        while (n > 0) {
            digits.add((int) (n % b));
            n /= b;
        }
        Collections.reverse(digits);
        return digits;
    }

    private int countValid(List<Integer> digits, int b) {
        int sz = digits.size();
        int[][][][] memo = new int[sz][b + 1][2][2];
        for (int[][][] a : memo) for (int[][] c : a) for (int[] d : c) Arrays.fill(d, -1);
        return dfs(0, 0, 1, 1, digits, b, memo);
    }

    private int dfs(int pos, int last, int isTight, int isLeading, List<Integer> digits, int b, int[][][][] memo) {
        if (pos == digits.size()) return 1;
        if (memo[pos][last][isTight][isLeading] != -1) return memo[pos][last][isTight][isLeading];
        int limit = (isTight == 1) ? digits.get(pos) : b - 1;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            if (isLeading == 1 && d == 0) {
                res = (res + dfs(pos + 1, 0, (isTight == 1 && d == limit) ? 1 : 0, 1, digits, b, memo)) % MOD;
            } else {
                if (d >= last) {
                    res = (res + dfs(pos + 1, d, (isTight == 1 && d == limit) ? 1 : 0, 0, digits, b, memo)) % MOD;
                }
            }
        }
        return memo[pos][last][isTight][isLeading] = (int) res;
    }

    private boolean isValid(String s, int b) {
        List<Integer> digs = toBaseB(s, b);
        for (int i = 0; i + 1 < digs.size(); i++) {
            if (digs.get(i) > digs.get(i + 1)) return false;
        }
        return true;
    }
}

var countNumbers = function(l, r, b) {
    const MOD = 1000000007;

    const toBaseB = s => {
        let n = BigInt(s);
        if (n === 0n) return [0];
        const digits = [];
        const base = BigInt(b);
        while (n > 0n) {
            digits.push(Number(n % base));
            n /= base;
        }
        return digits.reverse();
    };

    const countValid = digits => {
        const sz = digits.length;
        const memo = new Map();
        const dfs = (pos, last, isTight, isLeading) => {
            if (pos === sz) return 1;
            const key = `${pos},${last},${isTight},${isLeading}`;
            if (memo.has(key)) return memo.get(key);
            const limit = isTight ? digits[pos] : b - 1;
            let res = 0;
            for (let d = 0; d <= limit; d++) {
                if (isLeading && d === 0) {
                    res = (res + dfs(pos + 1, 0, isTight && (d === limit), true)) % MOD;
                } else {
                    if (d >= last) {
                        res = (res + dfs(pos + 1, d, isTight && (d === limit), false)) % MOD;
                    }
                }
            }
            memo.set(key, res);
            return res;
        };
        return dfs(0, 0, true, true);
    };

    const isValid = s => {
        const digs = toBaseB(s);
        for (let i = 0; i + 1 < digs.length; i++) {
            if (digs[i] > digs[i + 1]) return false;
        }
        return true;
    };

    const cntR = countValid(toBaseB(r));
    const cntL = countValid(toBaseB(l));
    const ans = (cntR - cntL + (isValid(l) ? 1 : 0)) % MOD;
    return (ans + MOD) % MOD;
};
